import java.util.*;

class Solution {
  List<Integer>[] g;
  int target, cuts;

  public int componentValue(int[] nums, int[][] edges) {
    int n = nums.length;
    g = new ArrayList[n];
    for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
    for (int[] e : edges) {
      g[e[0]].add(e[1]);
      g[e[1]].add(e[0]);
    }
    int sum = 0;
    for (int x : nums) sum += x;
    for (int parts = n; parts >= 1; parts--)
      if (sum % parts == 0) {
        target = sum / parts;
        cuts = 0;
        if (dfs(0, -1, nums) == 0) return parts - 1;
      }
    return 0;
  }

  int dfs(int u, int p, int[] a) {
    int s = a[u];
    for (int v : g[u])
      if (v != p) {
        int x = dfs(v, u, a);
        if (x < 0) return -1;
        s += x;
      }
    if (s == target) {
      cuts++;
      return 0;
    }
    return s > target ? -1 : s;
  }
}
